export function createElement(tag, props, children) {
  return { tag, props: props || {}, children: children || [] };
}

export function diff(oldTree, newTree) {
  const patches = [];

  const oldProps = oldTree.props || {};
  const newProps = newTree.props || {};

  for (const key of Object.keys(newProps)) {
    if (oldProps[key] !== newProps[key]) {
      patches.push({ type: 'SET_PROP', key, value: newProps[key] });
    }
  }

  for (const key of Object.keys(oldProps)) {
    if (!(key in newProps)) {
      patches.push({ type: 'REMOVE_PROP', key });
    }
  }

  const oldChildren = oldTree.children || [];
  const newChildren = newTree.children || [];
  const len = Math.max(oldChildren.length, newChildren.length);

  for (let i = 0; i < len; i++) {
    const oldChild = oldChildren[i];
    const newChild = newChildren[i];
    if (typeof oldChild === 'string' && typeof newChild === 'string') {
      if (oldChild !== newChild) {
        patches.push({ type: 'SET_TEXT', index: i, value: newChild });
      }
    } else if (oldChild && newChild && typeof oldChild === 'object' && typeof newChild === 'object') {
      const childPatches = diff(oldChild, newChild);
      childPatches.forEach(p => patches.push({ ...p, childIndex: i }));
    }
  }

  return patches;
}

export function patch(el, patches) {
  for (const p of patches) {
    if (p.type === 'SET_PROP') {
      el.setAttribute(p.key, p.value);
    } else if (p.type === 'REMOVE_PROP') {
      el.removeAttribute(p.key);
    } else if (p.type === 'SET_TEXT') {
      const index = p.index !== undefined ? p.index : 0;
      if (el.childNodes[index]) {
        el.childNodes[index].textContent = p.value;
      } else {
        el.textContent = p.value;
      }
    }
  }
}
